#!/bin/sh
set -eu
root=$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd)
java="$root/toolchain/runtime/jdk-full/jdk-21.0.12+8/Contents/Home/bin/java"; javac="$root/toolchain/runtime/jdk-full/jdk-21.0.12+8/Contents/Home/bin/javac"
cc="$root/toolchain/runtime/llvm-mos/bin/mos-mega65-clang"; objdump="$root/toolchain/runtime/llvm-mos/bin/llvm-objdump"; nm="$root/toolchain/runtime/llvm-mos/bin/llvm-nm"
c1541="$root/toolchain/vice-clean/bin/c1541"; petcat="$root/toolchain/vice/VICE.app/Contents/Resources/bin/petcat"; out="$root/build/r0e"; classes="$out/host-classes"
need(){ test -x "$java" && test -x "$javac" && test -x "$cc" && test -x "$objdump" && test -x "$nm" && test -x "$c1541" && test -x "$petcat"; }
hostc(){ mkdir -p "$classes"; "$javac" -d "$classes" "$root/tools/generators/src/main/java/f65/tools/R0EHostTools.java"; }
host(){ "$java" -Df65.root="$root" -cp "$classes" f65.tools.R0EHostTools "$@"; }
generate(){ need; hostc; host generate; }
hosttest(){ generate; host host-test; python3 "$root/tools/diagnostics/r0e_validate_target.py" "$root" --source-only; }
clean_c1541(){ report=$1; shift; stdout="$report.stdout"; stderr="$report.stderr"; rm -f "$stdout" "$stderr"; if ! "$c1541" "$@" >"$stdout" 2>"$stderr"; then cat "$stdout" "$stderr" >&2; return 1; fi; if test -s "$stderr" || rg -n -i 'warning|error|failed|fatal|duplicate|truncat|allocation|opencbm' "$stdout" "$stderr"; then cat "$stdout" "$stderr" >&2; return 1; fi; cat "$stdout" >"$report"; rm -f "$stdout" "$stderr"; }
build(){ hosttest; mkdir -p "$out/artifacts" "$out/reports"; "$cc" -mcpu=mos45gs02 -mlto-zp=0 -Os -Wall -Wextra -Wconversion -Werror -I"$root/interfaces/generated" "$root/src/r0e/main.c" "$root/src/diagnostics/r0e/composite.c" "$root/src/platform/r0a_platform_45gs02.s" -Wl,-Map,"$out/reports/F65-R0E-PROOF.map" -o "$out/artifacts/F65-R0E-PROOF.prg"; "$nm" "$out/artifacts/F65-R0E-PROOF.prg.elf" > "$out/reports/F65-R0E-PROOF.symbols"; "$objdump" -d --print-imm-hex "$out/artifacts/F65-R0E-PROOF.prg.elf" > "$out/reports/F65-R0E-PROOF.disassembly"; python3 "$root/tools/diagnostics/r0e_validate_target.py" "$root"; "$petcat" -w65 -o "$out/artifacts/AUTOBOOT.C65" -- "$root/src/r0e/autoboot.bas"; "$petcat" -65 "$out/artifacts/AUTOBOOT.C65" > "$out/reports/AUTOBOOT.C65.listing"; candidate="$out/artifacts/F65R0E.D81"; rm -f "$candidate" "$candidate.sha256"; clean_c1541 "$out/reports/F65R0E.D81-create.txt" -format 'F65 R0-E,65' d81 "$candidate" -write "$out/artifacts/AUTOBOOT.C65" autoboot.c65 -write "$out/artifacts/F65-R0E-PROOF.prg" r0e-proof -write "$out/artifacts/R0E-EVID.txt" r0e-evid -list; clean_c1541 "$out/reports/F65R0E.D81-list.txt" "$candidate" -list; python3 "$root/tools/diagnostics/r0e_d81_loadability_gate.py" "$root" "$candidate"; shasum -a 256 "$out/artifacts/F65-R0E-PROOF.prg" > "$out/artifacts/F65-R0E-PROOF.prg.sha256"; shasum -a 256 "$candidate" > "$candidate.sha256"; }
case ${1:-} in bootstrap) need; "$cc" --version; "$java" -version 2>&1;; generate) generate;; host-test) hosttest;; build) build;; verify) generate; host verify; python3 "$root/tools/diagnostics/r0e_validate_target.py" "$root" --source-only;; clean) rm -rf "$out";; *) echo 'usage: r0e.sh {bootstrap|generate|host-test|build|verify|clean}' >&2; exit 2;; esac
